<script setup lang="ts">import{onMounted}from'vue';import{storeToRefs}from'pinia';import{useOperationsStore}from'../stores/operations';const store=useOperationsStore();const{assets}=storeToRefs(store);onMounted(()=>store.refresh())</script>
<template><section class="page"><div class="page-title"><div><h1>设备台账</h1><p>设备位置、有效期和当前事件状态</p></div><div class="toolbar"><input placeholder="编号或区域"><select><option>全部类型</option><option>灭火器</option><option>消火栓</option></select></div></div><table class="table"><thead><tr><th>设备编号</th><th>类型</th><th>区域</th><th>有效期</th><th>状态</th></tr></thead><tbody><tr v-for="item in assets" :key="item.id"><td><b>{{item.code}}</b></td><td>{{item.kind}}</td><td>{{item.zone}}</td><td>{{item.expiresAt}}</td><td><span class="status" :class="item.status">{{item.status}}</span></td></tr></tbody></table></section></template>
